from typing import List

from deepdiff import DeepDiff
from deepdiff.operator import BaseOperator


class ListMatchOperator(BaseOperator):
    """Custom class for comparing lists."""

    IGNORE_DICTIONARY_ITEM_ADDED: bool = False

    def match(self, level) -> bool:
        """Method for triggering the operator."""
        return isinstance(level.t1, List)

    def give_up_diffing(self, level, diff_instance):
        """Method for finding the differences. In the case of different list lengths, the method checks
        whether all elements from the level.t1 list are in the level.t2 list."""
        differences = {}
        to_validate = list(level.t2)

        for index, item_t1 in enumerate(level.t1):  # expected params (eg our regexes)
            # Start comparing each item from level.t1 with level.t2 items
            differences[index] = []
            for validating_index, item_t2 in enumerate(to_validate):
                if handle_dictionary_item_added(
                    DeepDiff(item_t1, item_t2, custom_operators=[ListMatchOperator()]),
                    ignore_dictionary_item_added=self.IGNORE_DICTIONARY_ITEM_ADDED,
                ):
                    # list items don't match, store an item that is unmatched
                    differences[index] = item_t1
                else:
                    # list items match, so stop looking for item from level.t1 and remove them from the unmatched store
                    differences.pop(index)
                    to_validate.pop(validating_index)  # Remove the item from the list to avoid comparing it again
                    break
        # in the end of looping, differences contains only level.t1 items that don't match to any item from level.t2
        if differences:
            diff_instance.custom_report_result("items_not_found", level, extra_info=list(differences.values()))
            return False
        return True


def handle_dictionary_item_added(dd_result: dict, ignore_dictionary_item_added: bool) -> dict:
    """Remove dictionary_item_added result if needed by ignore_dictionary_item_added."""
    if ignore_dictionary_item_added and dd_result.get("dictionary_item_added", None):
        dd_result.pop("dictionary_item_added", None)
    return dd_result
